var exec=require('cordova/exec');module.exports={capture:function(ok,fail){exec(ok,fail,'NearbyPhotos','capture',[]);},nearby:function(lat,lon,radius,ok,fail){exec(ok,fail,'NearbyPhotos','nearby',[lat,lon,radius]);},thumbnail:function(id,ok,fail){exec(ok,fail,'NearbyPhotos','thumbnail',[id]);},pick:function(ok,fail){exec(ok,fail,'NearbyPhotos','pick',[]);}};